function findSectionStart(text, sectionName) {
  const regex = new RegExp(sectionName + '\\s*:?', 'i');
  const match = text.match(regex);
  return match ? text.indexOf(match[0]) + match[0].length : -1;
}

function extractSection(text, startPos, endPos) {
  if (startPos === -1) return '';
  return text.substring(startPos, endPos !== -1 ? endPos : text.length).trim();
}

const sectionDefs = [
  { key: 'ementa', pattern: 'Ementa' },
  { key: 'metodologia', pattern: 'Metodologia' },
  { key: 'procedimentos_avaliacao', pattern: 'Procedimentos de Avaliação' },
  { key: 'objetivos', pattern: 'Objetivos' },
  { key: 'conteudo_programatico', pattern: 'Conteúdo Programático' },
  { key: 'cronograma', pattern: 'Cronograma' },
  { key: 'avaliacoes', pattern: 'Avaliações' },
  { key: 'horario_atendimento', pattern: 'Horário de Atendimento' },
  { key: 'referencias', pattern: 'Referências' }
];

return $input.all().map(item => {
  const text = item.json.text || '';

  const sectionPositions = sectionDefs.map(s => ({
    key: s.key,
    position: findSectionStart(text, s.pattern)
  })).filter(s => s.position !== -1).sort((a, b) => a.position - b.position);

  const result = {};
  result.identificacao = text.substring(0, 500).trim();

  for (let i = 0; i < sectionPositions.length; i++) {
    const cur = sectionPositions[i];
    const next = sectionPositions[i + 1];
    const content = extractSection(text, cur.position, next ? next.position : -1);

    if (cur.key === 'objetivos') {
      const geralStart = content.indexOf('GERAL:');
      const espStart = content.indexOf('ESPECÍFICOS:');
      result['objetivos_geral'] = geralStart !== -1
        ? content.substring(geralStart + 6, espStart !== -1 ? espStart : content.length).trim()
        : '';
      result['objetivos_especificos'] = espStart !== -1
        ? content.substring(espStart + 13).trim()
        : '';
    } else {
      result[cur.key] = content;
    }
  }

  return { json: result };
});

return $input.all().map((item, index) => {
const sections = item.json;

// Recupera o nome do arquivo do nó de busca (mantido no lineage do item)
const fileName = $('Search files and folders').all()[index]?.json.name || 'arquivo_desconhecido';
const trunc = (str, max = 800) => str ? str.substring(0, max) + (str.length > max ? '...' : '') : '(não preenchido)';

// ⚙️ CONFIGURE O MODELO AQUI (ex: llama3, mistral, llama3.2, gemma2)
const OLLAMA_MODEL = 'llama3.2';

const prompt = `Você é um especialista em avaliação de planos de ensino acadêmicos brasileiros.
Analise os campos abaixo e retorne APENAS um JSON válido, sem texto adicional, sem markdown.

Critérios para cada campo:
- "OK": campo completo, coerente e adequado
- "INCOMPLETO": preenchido mas insuficiente (muito curto, genérico ou inconsistente)
- "AUSENTE": campo vazio ou não encontrado

Regras específicas:
- identificacao: deve conter instituição, componente curricular e nome do docente
- referencias: deve ter no mínimo 3 referências básicas e 5 complementares; se tiver menos, marque INCOMPLETO e diga quantas encontrou
- procedimentos_avaliacao: verifique também se menciona interdisciplinaridade
- coerencia: avalie se os objetivos são compatíveis com a metodologia e se os procedimentos de avaliação combinam com os objetivos

Status geral:
- "OK": todos os campos estão OK
- "PENDENTE": um ou mais campos estão INCOMPLETO
- "REPROVADO": um ou mais campos estão AUSENTE

Formato de retorno (JSON puro):
{
  "identificacao": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "ementa": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "metodologia": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "procedimentos_avaliacao": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "objetivos_geral": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "objetivos_especificos": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "conteudo_programatico": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "cronograma": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "avaliacoes": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "referencias": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "horario_atendimento": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "coerencia": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "status_geral": "OK|PENDENTE|REPROVADO",
  "obs_geral": "resumo geral do plano em 1 frase"
}

DADOS DO PLANO DE ENSINO:

IDENTIFICAÇÃO (início do documento):
${trunc(sections.identificacao)}

EMENTA:
${trunc(sections.ementa)}

METODOLOGIA:
${trunc(sections.metodologia)}

PROCEDIMENTOS DE AVALIAÇÃO:
${trunc(sections.procedimentos_avaliacao)}

OBJETIVOS GERAL:
${trunc(sections.objetivos_geral)}

OBJETIVOS ESPECÍFICOS:
${trunc(sections.objetivos_especificos)}

CONTEÚDO PROGRAMÁTICO:
${trunc(sections.conteudo_programatico)}

CRONOGRAMA:
${trunc(sections.cronograma)}

AVALIAÇÕES:
${trunc(sections.avaliacoes)}

HORÁRIO DE ATENDIMENTO:
${trunc(sections.horario_atendimento)}

REFERÊNCIAS:
${trunc(sections.referencias)}`;

return {
    json: {
      fileName,
      ollamaPayload: JSON.stringify({
        model: OLLAMA_MODEL,
        prompt,
        stream: false,
        options: { num_predict: 2048, temperature: 0.1 }
      })
    }
  };
});

return $input.all().map((item, index) => {
  const response = item.json;
  const fileName = $('Preparar Prompt').all()[index]?.json.fileName || 'arquivo_desconhecido';

  let validacao;
  try {
    const rawText = response.response || '';
    const jsonMatch = rawText.match(/\{[\s\S]*\}/);
    const jsonStr = jsonMatch ? jsonMatch[0] : rawText;
    validacao = JSON.parse(jsonStr);
  } catch (e) {
    validacao = {
      status_geral: 'ERRO',
      obs_geral: 'Falha ao processar resposta da IA: ' + e.message
    };
  }

  const s = (field) => validacao[field]?.status || 'ERRO';
  const o = (field) => validacao[field]?.obs || '';

  return {
    json: {
      'Arquivo': fileName,
      'Data Validação': new Date().toLocaleString('pt-BR'),
      'Status Geral': validacao.status_geral || 'ERRO',
      'Observação Geral': validacao.obs_geral || '',
      'Ementa': s('ementa'),
      'Ementa Obs': o('ementa'),
      'Metodologia': s('metodologia'),
      'Metodologia Obs': o('metodologia'),
      'Proc. Avaliação': s('procedimentos_avaliacao'),
      'Proc. Avaliação Obs': o('procedimentos_avaliacao'),
      'Objetivos Geral': s('objetivos_geral'),
      'Objetivos Geral Obs': o('objetivos_geral'),
      'Objetivos Específicos': s('objetivos_especificos'),
      'Objetivos Específicos Obs': o('objetivos_especificos'),
      'Conteúdo Programático': s('conteudo_programatico'),
      'Conteúdo Programático Obs': o('conteudo_programatico'),
      'Cronograma': s('cronograma'),
      'Cronograma Obs': o('cronograma'),
      'Avaliações': s('avaliacoes'),
      'Avaliações Obs': o('avaliacoes'),
      'Referências': s('referencias'),
      'Referências Obs': o('referencias'),
      'Identificação': s('identificacao'),
      'Identificação Obs': o('identificacao'),
      'Horário Atendimento': s('horario_atendimento'),
      'Horário Atendimento Obs': o('horario_atendimento'),
      'Coerência': s('coerencia'),
      'Coerência Obs': o('coerencia')
    }
  };
});
